Object.assign(words,{footer:['نسخه ۱.۳ · ویندوز','Version 1.3 · Windows'],location_capacity:['ظرفیت جایگاه','Location capacity'],category_parent:['شاخه‌بندی دسته‌ها','Category hierarchy'],bulk_products:['ویرایش گروهی کالاها','Bulk product update'],variants_generate:['ساخت مدل‌های کالا','Generate product variants'],purchase_request:['درخواست خرید','Purchase request'],purchase_request_approve:['تأیید درخواست خرید','Approve purchase request'],purchase_request_order:['سفارش از درخواست','Order from request'],order_reserve:['رزرو سفارش معوق','Reserve backorder'],pick_scan:['تأیید بارکد برداشت','Verify pick barcode'],quality_inspect:['بررسی سلامت مرجوعی','Return quality inspection'],custom_role:['تعریف نقش','Define role'],customRoles:['تعریف نقش سفارشی','Custom role'],permissions:['مجوزها','Permissions'],exportExcel:['خروجی اکسل','Export Excel'],importExcel:['ورود از اکسل','Import Excel'],report_schedule:['گزارش روزانه روی دیسک','Daily report on disk'],automation_rule:['قاعده اعلان خودکار','Automatic notification rule'],trigger:['شرط اعلان','Notification trigger'],scheduledFiles:['گزارش‌های آماده','Generated reports']});
